                        livecrawl="preferred"
                    )
                elif search_type == 'auto':
                    result = self.exa.search_and_contents(
                        query=query,
                        type="auto",
                        num_results=100,
                        text=True,
                        highlights=True,
                        livecrawl="preferred"
                    )
                else:
                    result = self.exa.search(query=query, type="fast", num_results=100)

                return {'query': query, 'type': search_type, 'results': result.results}
            except Exception as e:
                return {'query': query, 'type': search_type, 'results': [], 'error': str(e)}

        with ThreadPoolExecutor(max_workers=24) as executor:
