    def autonomous_research(self, query: str, max_duration_minutes: int = 90) -> Dict:
        session_id = self.generate_session_id(query)
        start_time = time.time()

        self.update_state(
            session_id=session_id,
            status='running',
            start_time=start_time,
            progress=0,
            current_action='Initializing autonomous research agent'
        )

        try:
            query_analysis = self.analyze_query_with_thinking_model(query)
            self.update_state(queries=query_analysis['search_queries'], progress=10)

            initial_searches = self.parallel_exa_search(query_analysis['search_queries'])

            all_sources = []
            all_urls = set()

            for search_result in initial_searches:
                for result in search_result.get('results', []):
                    if hasattr(result, 'url') and result.url not in all_urls:
                        all_urls.add(result.url)
                        all_sources.append({
                            'url': result.url,
                            'title': getattr(result, 'title', ''),
                            'text': getattr(result, 'text', ''),
                            'highlights': getattr(result, 'highlights', [])
                        })

            self.update_state(sources=all_sources, progress=25)

            iterations = self.iterative_research_loop(query, max_iterations=15)
            self.update_state(progress=85)

            all_data = {
                'query': query,
                'query_analysis': query_analysis,
                'sources': all_sources,
                'iterations': iterations,
                'total_sources': len(all_sources),
                'session_id': session_id
            }

            final_report = self.synthesize_final_report(all_data)

            self.update_state(
                status='completed',
                progress=100,
                current_action='Research complete'
            )

            result = {
                'session_id': session_id,
                'query': query,
                'report': final_report,
                'metadata': {
                    'total_sources': len(all_sources),
                    'iterations': len(iterations),
                    'duration_seconds': time.time() - start_time
                }
            }

            self.redis_dragonfly_1.setex(f"report:{session_id}", 86400, json.dumps(result))
            self.redis_dragonfly_2.setex(f"report:{session_id}", 86400, json.dumps(result))
            self.redis_dragonfly_3.setex(f"report:{session_id}", 86400, json.dumps(result))

            return result

        except Exception as e:
            self.update_state(
                status='error',
                current_action=f'Error: {str(e)}'
            )
            return {
                'session_id': session_id,
                'error': str(e),
                'partial_state': self.research_state
            }

from flask import Flask, request, jsonify, Response
