import json

app = Flask(__name__)
CORS(app)

agent = DeepSearchAgent()

@app.route('/api/research', methods=['POST'])
def start_research():
    data = request.json
    query = data.get('query', '')

    if not query:
        return jsonify({'error': 'Query is required'}), 400

    session_id = agent.generate_session_id(query)

    def research_task():
        agent.autonomous_research(query)

    import threading
    thread = threading.Thread(target=research_task)
    thread.daemon = True
    thread.start()

    return jsonify({'session_id': session_id})

@app.route('/api/status/<session_id>', methods=['GET'])
def get_status(session_id):
    state = agent.get_state(session_id)
    if not state:
        return jsonify({'error': 'Session not found'}), 404
    return jsonify(state)

@app.route('/api/stream/<session_id>', methods=['GET'])
def stream_status(session_id):
    def generate():
        for _ in range(360):
            state = agent.get_state(session_id)
            if state:
                yield f"data: {json.dumps(state)}\n\n"
                if state.get('status') in ['completed', 'error']:
                    break
            time.sleep(5)

    return Response(generate(), mimetype='text/event-stream')

@app.route('/api/report/<session_id>', methods=['GET'])
def get_report(session_id):
    try:
        report_data = agent.redis_dragonfly_1.get(f"report:{session_id}")
        if not report_data:
            return jsonify({'error': 'Report not found'}), 404
        return jsonify(json.loads(report_data))
    except:
        return jsonify({'error': 'Error retrieving report'}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, threaded=True)
