            }

    def replan(self, original_plan: Dict, execution_results: Dict, iteration: int) -> Dict:
        replan_prompt = f"""You are replanning research strategy based on execution results.

Original plan objectives: {json.dumps(original_plan.get('objectives', []))}

Execution iteration: {iteration}
Results summary: {json.dumps(execution_results, indent=2)[:5000]}

Analyze what's working and what's not. Create an updated plan that:
1. Doubles down on successful strategies
2. Abandons unproductive approaches
3. Explores new angles based on findings
4. Adjusts priorities based on results

Return updated plan as JSON with same structure as original."""

        try:
            response = self.xai.chat.completions.create(
                model="grok-4-fast",
                messages=[{"role": "user", "content": replan_prompt}],
                max_tokens=32768,
                temperature=0.7
            )

            updated_plan = json.loads(response.choices[0].message.content)
            return updated_plan
        except:
            return original_plan

class CriticModule:
