    def iterative_refinement_loop(self, query: str, initial_plan: Dict, max_iterations: int = 10) -> Dict:
        all_sources = []
        all_syntheses = []
        iteration_history = []
        current_plan = initial_plan

        for iteration in range(max_iterations):
            self.update_state(
                current_action=f'Refinement iteration {iteration + 1}/{max_iterations}',
                current_phase=f'Iteration {iteration + 1}',
                progress=60 + (iteration * 3)
            )

            search_results = self.dynamic_search_execution(current_plan, iteration)
            new_sources = search_results['sources']

            all_sources.extend(new_sources)

            unique_sources = {}
            for source in all_sources:
                url = source.get('url', '')
                if url:
                    unique_sources[url] = source

            all_sources = list(unique_sources.values())

            if iteration % 2 == 0:
                urls_to_expand = [s['url'] for s in new_sources[:30]]
                expanded_content = self.deep_content_discovery(urls_to_expand, iteration)
                all_sources.extend(expanded_content)

            perspectives = [
                'technical and scientific',
                'business and economic',
                'social and ethical',
                'future trends and predictions',
                'risks and challenges'
            ]

            perspective = perspectives[iteration % len(perspectives)]
            synthesis = self.multi_model_synthesis(all_sources[-200:], perspective, iteration)
            all_syntheses.append(synthesis)

            iteration_summary = {
                'iteration': iteration + 1,
                'sources_found': len(new_sources),
                'total_sources': len(all_sources),
                'perspective': perspective,
                'performance': search_results.get('performance', [])
            }
            iteration_history.append(iteration_summary)

            if iteration < max_iterations - 1 and iteration % 3 == 2:
                execution_results = {
                    'iterations': iteration_history,
                    'sources_count': len(all_sources),
                    'synthesis_summary': all_syntheses[-1]
                }

                current_plan = self.planner.replan(current_plan, execution_results, iteration)

                self.update_state(
