class MultiRedis:
    def __init__(self):
        self.clients = []
        try:
            url = os.getenv('DRAGONFLY_REDIS_URL')
            if url:
                self.clients.append(redis.from_url(url, decode_responses=True))
        except:
            pass
        try:
            self.clients.append(redis.from_url("rediss://default:ddakvoa79hk3@0hxia2s5w.dragonflydb.cloud:6385", decode_responses=True))
        except:
