        try:
            self.clients.append(redis.from_url("rediss://default:4s6z877px3x1@zy0n0f6e8.dragonflydb.cloud:6385", decode_responses=True))
        except:
            pass

    def setex(self, key: str, ttl: int, value: str):
        ok = False
        for c in self.clients:
            try:
                c.setex(key, ttl, value)
                ok = True
            except:
                pass
        return ok

    def get(self, key: str) -> Optional[str]:
        for c in self.clients:
            try:
                v = c.get(key)
                if v is not None:
                    return v
            except:
                pass
        return None

    def publish(self, channel: str, message: str):
        for c in self.clients:
            try:
                c.publish(channel, message)
            except:
                pass

    def lpush(self, key: str, value: str):
        for c in self.clients:
            try:
                c.lpush(key, value)
            except:
                pass

    def rpop(self, key: str) -> Optional[str]:
        for c in self.clients:
            try:
                v = c.rpop(key)
                if v:
                    return v
            except:
                pass
        return None

    def pubsub(self):
        if self.clients:
            try:
                return self.clients[0].pubsub()
            except:
                pass
        raise RuntimeError("No Redis clients available for pubsub")

class KnowledgeGraph:
    def __init__(self, store: MultiRedis):
        self.store = store

    def _node_key(self, name: str) -> str:
        return f"kg:node:{hashlib.sha256(name.lower().encode()).hexdigest()}"

    def _rel_key(self, src: str, rel: str, dst: str) -> str:
        return f"kg:edge:{hashlib.sha256(f'{src}|{rel}|{dst}'.encode()).hexdigest()}"

    def add_entity(self, name: str, etype: str, metadata: Dict[str, Any]):
        nid = self._node_key(name)
        node = {
            "name": name,
            "type": etype,
            "metadata": metadata,
            "created_at": time.time()
        }
        self.store.setex(nid, 365*24*3600, json.dumps(node))
        idx_key = "kg:nodes:index"
        self.store.lpush(idx_key, nid)
        return nid

    def add_relation(self, src: str, rel: str, dst: str, evidence: Dict[str, Any], weight: float):
        rid = self._rel_key(src, rel, dst)
        edge = {
            "src": src,
            "rel": rel,
            "dst": dst,
            "evidence": evidence,
            "weight": weight,
            "created_at": time.time()
        }
        self.store.setex(rid, 365*24*3600, json.dumps(edge))
        idx_key = f"kg:edges:index:{hashlib.sha256(src.encode()).hexdigest()}"
        self.store.lpush(idx_key, rid)
        return rid

    def get_entity(self, name: str) -> Optional[Dict[str, Any]]:
        nid = self._node_key(name)
        raw = self.store.get(nid)
        if raw:
            return json.loads(raw)
        return None

    def neighbors(self, name: str, limit: int = 50) -> Dict[str, List[Dict[str, Any]]]:
        src_key = f"kg:edges:index:{hashlib.sha256(name.encode()).hexdigest()}"
        results = []
        for _ in range(limit):
            raw = self.store.rpop(src_key)
            if not raw:
                break
            edge_json = self.store.get(raw)
            if edge_json:
                results.append(json.loads(edge_json))
        return {"edges": results}

class EmbeddingMemory:
    def __init__(self, store: MultiRedis):
        self.store = store

    def _emb_key(self, session_id: str) -> str:
        return f"mem:embeddings:{session_id}"

    def _global_index_key(self) -> str:
        return "mem:embeddings:index"

    def store_vector(self, session_id: str, text: str, vector: List[float], metadata: Dict[str, Any]):
        vid = hashlib.sha256(f"{text}{time.time()}".encode()).hexdigest()
        item = {
            "id": vid,
            "session_id": session_id,
            "text": text,
            "vector": vector,
            "metadata": metadata,
            "timestamp": time.time()
        }
        self.store.setex(f"mem:vector:{vid}", 365*24*3600, json.dumps(item))
        self.store.lpush(self._emb_key(session_id), vid)
        self.store.lpush(self._global_index_key(), vid)
        return vid

    def recall_by_session(self, session_id: str, limit: int = 50) -> List[Dict[str, Any]]:
        key = self._emb_key(session_id)
        results = []
        for _ in range(limit):
            vid = self.store.rpop(key)
            if not vid:
                break
            raw = self.store.get(f"mem:vector:{vid}")
            if raw:
                results.append(json.loads(raw))
        return results

