        return hashlib.sha256(f"{query}|{time.time()}|{random.random()}".encode()).hexdigest()[:16]

    def _save_state(self, session_id: str, state: Dict[str, Any]):
        with self.state_lock:
            self.session_states[session_id] = state
        self.store.setex(f"session:{session_id}", 7200, json.dumps(state, default=str))
        self.store.publish(f"events:{session_id}", json.dumps(state, default=str))

    def _update_state(self, session_id: str, **kwargs):
        with self.state_lock:
            s = self.session_states.get(session_id, {})
            s.update(kwargs)
            self.session_states[session_id] = s
        self.store.setex(f"session:{session_id}", 7200, json.dumps(self.session_states[session_id], default=str))
        self.store.publish(f"events:{session_id}", json.dumps(self.session_states[session_id], default=str))

    def recall_memory(self, session_id: str, query: str) -> List[Dict[str, Any]]:
        recalled = []
        return recalled

    def extract_entities_relations(self, text: str) -> Dict[str, Any]:
        prompt = "Extract named entities and relations from the following text and return strict JSON with keys entities and relations where entities are objects with name and type and relations are objects with src, rel, dst and evidence snippet.\n\n" + text[:20000]
        raw = self.hub.generate_gpt_oss(prompt, max_tokens=8192, temperature=0.2)
        try:
            return json.loads(raw)
        except:
            return {"entities": [], "relations": []}

    def enrich_knowledge_graph(self, session_id: str, sources: List[Dict[str, Any]]):
        chunks = []
        buf = ""
        for s in sources[:80]:
            t = s.get("text", "")
            if len(t) > 2000:
                t = t[:2000]
            buf += t + "\n"
            if len(buf) > 15000:
                chunks.append(buf)
                buf = ""
        if buf:
            chunks.append(buf)
        for ch in chunks:
            try:
                er = self.extract_entities_relations(ch)
                for e in er.get("entities", []):
                    self.kg.add_entity(e.get("name",""), e.get("type","unknown"), {"session_id": session_id})
                for r in er.get("relations", []):
                    self.kg.add_relation(r.get("src",""), r.get("rel",""), r.get("dst",""), {"snippet": r.get("evidence","")}, 0.5)
            except:
                pass

    def generate_hypotheses(self, query: str, k: int = 16) -> List[str]:
        prompt = f"Generate {k} distinct, testable research hypotheses or strategic angles about the topic as a JSON array under key hypotheses for query: {query}"
        raw = self.hub.generate_qwen_thinking(prompt, max_tokens=8192, temperature=0.95)
        try:
            data = json.loads(raw)
            arr = data.get("hypotheses", [])
            if isinstance(arr, list):
                return [str(x) for x in arr][:k]
        except:
            pass
        lines = [l.strip() for l in raw.split("\n") if l.strip()]
        return lines[:k]

    def score_sources(self, sources: List[Dict[str, Any]]) -> List[Tuple[float, Dict[str, Any]]]:
        scored = []
        for s in sources:
            score = 0.0
            if s.get("highlights"):
                score += min(1.0, len(s["highlights"]) / 5.0)
            if s.get("published_date"):
                score += 0.3
            if len(s.get("text","")) > 1000:
                score += 0.5
            scored.append((score, s))
        scored.sort(key=lambda x: x[0], reverse=True)
        return scored

    def simulate_parallel_realities(self, session_id: str, query: str, hypotheses: List[str]) -> Dict[str, Any]:
        self._update_state(session_id, current_action="Párhuzamos kutatási útvonalak indítása", current_phase="Parallel Realities", progress=10)
        results = []

        def run_path(h):
            try:
                self.store.publish(f"events:{session_id}", json.dumps({"event":"thought","message":f"Útvonal indul: {h}","ts":time.time()}))
                found = self.exa.search_comprehensive(h, {})
                top = [s for _, s in self.score_sources(found)][:40]
                brief = "Állítások és ellentmondások keresése az alábbi források alapján.\n\n" + "\n\n".join([s.get("text","")[:1500] for s in top[:12]])
                check = self.hub.generate_gpt_oss(f"Elemezd az összefüggéseket és ellentmondásokat tömören JSON-ben under key findings, contradictions, signals.\n\n{brief}", max_tokens=12000, temperature=0.4)
                out = {"hypothesis": h, "sources": top, "analysis": check}
                return out
            except Exception as e:
                return {"hypothesis": h, "error": str(e), "sources": [], "analysis": ""}

        futures = []
        for h in hypotheses:
            futures.append(self.thread_pool.submit(run_path, h))
        for fut in as_completed(futures):
            res = fut.result()
            results.append(res)
            self.store.publish(f"events:{session_id}", json.dumps({"event":"update","message":"Útvonal kész", "hypothesis":res.get("hypothesis",""),"sources":len(res.get("sources",[])),"ts":time.time()}))
        scored_paths = []
        for r in results:
            sc = len(r.get("sources", []))
            if "error" in r and r["error"]:
                sc = 0
            scored_paths.append((sc, r))
        scored_paths.sort(key=lambda x: x[0], reverse=True)
        top_paths = [r for _, r in scored_paths[:5]]
        return {"all_paths": results, "top_paths": top_paths}

    def continuous_live_updates(self, session_id: str, tracked_queries: List[str], stop_event: threading.Event):
        while not stop_event.is_set():
            try:
                for tq in tracked_queries:
                    upd = self.exa.search_comprehensive(tq, {"start_published_date": datetime.utcnow().strftime("%Y-%m-%d")})
                    if upd:
                        self.store.publish(f"events:{session_id}", json.dumps({"event":"live_update","query":tq,"new_items":len(upd),"ts":time.time()}))
                for _ in range(12):
                    if stop_event.is_set():
                        break
                    time.sleep(10)
            except:
                time.sleep(10)

    def human_control_check(self, session_id: str) -> Optional[Dict[str, Any]]:
        cmd = self.store.rpop(f"control:{session_id}")
        if not cmd:
            return None
        try:
            return json.loads(cmd)
        except:
            return {"type":"unknown","raw":cmd}

    def interactive_decision_point(self, session_id: str, options: List[str]) -> str:
        self.store.publish(f"events:{session_id}", json.dumps({"event":"decision","options":options,"ts":time.time()}))
        start = time.time()
        chosen = None
        while time.time() - start < 180:
            cmd = self.human_control_check(session_id)
            if cmd and cmd.get("type") == "choose" and cmd.get("option") in options:
                chosen = cmd.get("option")
                break
            time.sleep(2)
        if not chosen:
            chosen = options[0]
        return chosen

    def multi_model_synthesis(self, session_id: str, sources: List[Dict[str, Any]], perspective: str) -> Dict[str, Any]:
        text = "\n\n".join([s.get("text","")[:2500] for s in sources[:80]])
        prompt = f"Nézőpont: {perspective}\n\nForrásrészletek:\n{text}\n\nAdj mély, részletes szintézist."
        gpt = self.hub.generate_gpt_oss(prompt, max_tokens=30000, temperature=0.6)
        qwen = self.hub.generate_qwen_thinking(prompt, max_tokens=30000, temperature=0.7)
        grok = self.hub.generate_grok_fast(prompt, max_tokens=30000, temperature=0.7)
        claude = self.hub.generate_claude_sonnet(prompt, max_tokens=200000, temperature=0.65, one_million_context=True)
        return {"perspective": perspective, "models": {"gpt-oss-120b": gpt, "qwen-235b-thinking": qwen, "grok-4-fast": grok, "claude-sonnet-4.5": claude}}

    def critic_cycle(self, session_id: str, draft: str, sources: List[Dict[str, Any]]) -> Dict[str, Any]:
        src = "\n".join([f"- {s.get('title','')} {s.get('url','')}" for s in sources[:40]])
        critique_prompt = f"Kritika tárgy: \n{draft[:18000]}\n\nForrások:\n{src}\n\nAdj részletes kritikát JSON-ben logical_issues, gaps, biases, contradictions, unanswered_questions, alternatives, recommendations, overall_confidence."
        critique = self.hub.generate_claude_sonnet(critique_prompt, max_tokens=150000, temperature=0.7, one_million_context=True)
        defense_prompt = f"Eredeti megállapítások:\n{draft[:14000]}\n\nKritika:\n{critique[:14000]}\n\nVédekezés vagy revízió JSON-ben defended, revised, acknowledged_gaps, new_research_needed."
        defense = self.hub.generate_gpt_oss(defense_prompt, max_tokens=30000, temperature=0.55)
        try:
            return {"critique": json.loads(critique) if isinstance(critique, str) and critique.strip().startswith("{") else {"text": critique}, "defense": json.loads(defense) if isinstance(defense, str) and defense.strip().startswith("{") else {"text": defense}}
        except:
            return {"critique": {"text": critique}, "defense": {"text": defense}}

    def generate_final_report(self, session_id: str, query: str, syntheses: List[Dict[str, Any]], sources: List[Dict[str, Any]], critique: Dict[str, Any]) -> str:
        syn = []
        for s in syntheses:
            blk = f"{s.get('perspective','')}\n" + "\n".join([f"{m}: {v[:4000] if isinstance(v,str) else str(v)[:4000]}" for m, v in s.get("models", {}).items()])
            syn.append(blk)
        srcs = "\n".join([f"[{i+1}] {s.get('title','')} ({s.get('url','')})" for i, s in enumerate(sources[:300])])
        prompt = f"Eredeti kérdés: {query}\n\nSzintézisek:\n{chr(10).join(syn)[:120000]}\n\nKritika és védekezés:\n{json.dumps(critique, ensure_ascii=False)[:40000]}\n\nForrások:\n{srcs}\n\nKészíts 20-30 oldalas részletes professzionális jelentést az alábbi fejezetekkel: Executive Summary, Methodology, Comprehensive Findings, Critical Analysis, Implications and Recommendations, Future Outlook, Conclusion, References."
        report = self.hub.generate_claude_sonnet(prompt, max_tokens=200000, temperature=0.6, one_million_context=True)
        enhanced = self.hub.generate_claude_sonnet("Bővítsd és mélyítsd tovább a jelentést.\n\n" + report[:150000], max_tokens=200000, temperature=0.55, one_million_context=True)
        return enhanced

    def run_research(self, query: str, max_minutes: int = 90) -> Dict[str, Any]:
        session_id = self._sid(query)
        state = {
            "session_id": session_id,
            "query": query,
            "status": "running",
            "progress": 0,
            "current_action": "Inicializálás",
            "current_phase": "Init",
            "start_time": time.time(),
            "iterations": [],
            "plan": {},
            "sources": [],
            "syntheses": [],
            "critique": {}
        }
        self._save_state(session_id, state)
        stop_event = threading.Event()
        live_thread = None
        try:
            self._update_state(session_id, current_action="Hipotézisek generálása", current_phase="Planning", progress=3)
            hypotheses = self.generate_hypotheses(query, k=24)
            self.store.publish(f"events:{session_id}", json.dumps({"event":"hypotheses","items":hypotheses,"ts":time.time()}))
            self._update_state(session_id, current_action="Párhuzamos útvonalak futtatása", progress=8)
            realities = self.simulate_parallel_realities(session_id, query, hypotheses)
            top_paths = realities.get("top_paths", [])
            all_sources = []
            for p in top_paths:
                all_sources.extend(p.get("sources", []))
            uniq = {}
            for s in all_sources:
                u = s.get("url","")
                if u and u not in uniq:
                    uniq[u] = s
            all_sources = list(uniq.values())
            self._update_state(session_id, current_action=f"Források mélyítése {len(all_sources)}", progress=18)
            deep = []
            sim = []
            with ThreadPoolExecutor(max_workers=24) as pool:
                futs = []
                for s in all_sources[:60]:
                    futs.append(pool.submit(self.exa.deep_contents, s.get("url","")))
                    futs.append(pool.submit(self.exa.similar, s.get("url","")))
                for f in as_completed(futs):
                    try:
                        r = f.result()
                        if r and isinstance(r, list) and r and isinstance(r[0], dict) and "via" in r[0] and r[0]["via"] == "subpages":
                            deep.extend(r)
                        else:
                            sim.extend(r)
                    except:
                        pass
            combined_sources = all_sources + deep + sim
            uniq2 = {}
            for s in combined_sources:
                u = s.get("url","")
                if u and u not in uniq2:
                    uniq2[u] = s
            combined_sources = list(uniq2.values())
            self._update_state(session_id, sources=combined_sources[:500], current_action=f"KG építése {len(combined_sources)} forrásból", progress=28)
            threading.Thread(target=self.enrich_knowledge_graph, args=(session_id, combined_sources[:120]), daemon=True).start()
            live_thread = threading.Thread(target=self.continuous_live_updates, args=(session_id, [query], stop_event), daemon=True)
            live_thread.start()
            self._update_state(session_id, current_action="Dinamikus ügynökök létrehozása", current_phase="Agents", progress=32)
            roles = DynamicAgentFactory(self.hub).specialize_roles(query)
            agent_results = []
            with ThreadPoolExecutor(max_workers=16) as pool:
                futs = [pool.submit(DynamicAgentFactory(self.hub).run_agent, r, query, combined_sources[:120]) for r in roles]
                for f in as_completed(futs):
                    try:
                        agent_results.append(f.result())
                    except:
                        pass
            self._update_state(session_id, current_action="Soknézőpontos szintézis", current_phase="Synthesis", progress=48)
            perspectives = ["technikai és tudományos", "üzleti és gazdasági", "társadalmi és etikai", "jövőbeli trendek", "kockázatok és kihívások"]
            syntheses = []
            with ThreadPoolExecutor(max_workers=8) as pool:
                futs = [pool.submit(self.multi_model_synthesis, session_id, combined_sources[:240], p) for p in perspectives]
                for f in as_completed(futs):
                    try:
                        syntheses.append(f.result())
                        self._update_state(session_id, current_action="Szintézis folyamatban", progress=min(85, self.session_states[session_id]["progress"]+3))
                    except:
                        pass
            self._update_state(session_id, current_action="Kritika és revízió ciklus", current_phase="Critic", progress=86)
            draft = "\n\n".join([json.dumps(s)[:3000] if not isinstance(s, str) else s[:3000] for s in [ar.get("output","") if isinstance(ar, dict) else "" for ar in agent_results][:3]])
            crit = self.critic_cycle(session_id, draft, combined_sources[:120])
            self._update_state(session_id, current_action="Jelentés generálása", current_phase="Report", progress=92)
            report = self.generate_final_report(session_id, query, syntheses, combined_sources[:300], crit)
            self._update_state(session_id, current_action="Mentés és memória frissítés", progress=96)
            self.store.setex(f"report:{session_id}", 86400, json.dumps({"session_id": session_id, "query": query, "report": report, "sources_count": len(combined_sources)}, default=str))
            self._update_state(session_id, status="completed", current_action="Kész", current_phase="Completed", progress=100, syntheses=syntheses, critique=crit)
            return {"session_id": session_id, "report": report, "sources": combined_sources[:200], "syntheses": syntheses, "critique": crit}
        except Exception as e:
            err = {"error": str(e), "trace": traceback.format_exc()}
            self._update_state(session_id, status="error", current_action="Hiba", error=err)
            return {"session_id": session_id, "error": err}
        finally:
            if stop_event and live_thread:
                stop_event.set()

