                "function": {
                    "name": "find_similar_and_deepen",
                    "description": "Finds web pages similar to a given URL to expand on a promising source. Returns the content of these similar pages.",
                    "parameters": {
                        "type": "object",
                        "properties": {"url": {"type": "string", "description": "The URL of the source to find similar content for."}},
                        "required": ["url"],
                    },
                },
            },
            {
                "type": "function",
                "function": {
                    "name": "get_full_content_and_subpages",
                    "description": "Retrieves the full text content of a specific URL and explores its subpages to gather in-depth information from a single domain.",
                    "parameters": {
                        "type": "object",
                        "properties": {
                            "url": {"type": "string", "description": "The base URL to explore."},
                            "subpage_limit": {"type": "integer", "description": "Maximum number of subpages to crawl (e.g., 10)."},
                        },
                        "required": ["url", "subpage_limit"],
                    },
                },
            },
            {
                "type": "function",
                "function": {
                    "name": "add_sources_to_knowledge_base",
                    "description": "Adds a list of high-quality URLs to a topic-specific knowledge base (Webset) for future use.",
                    "parameters": {
                        "type": "object",
                        "properties": {
                            "topic_name": {"type": "string", "description": "The name of the knowledge base, e.g., 'Quantum_Computing_Research'."},
                            "urls": {"type": "array", "items": {"type": "string"}, "description": "A list of URLs to add."},
                        },
                        "required": ["topic_name", "urls"],
                    },
                },
            },
            {
                "type": "function",
                "function": {
                    "name": "query_internal_knowledge_base",
                    "description": "Searches for information within a previously created internal knowledge base (Webset).",
                    "parameters": {
                        "type": "object",
                        "properties": {
                            "topic_name": {"type": "string", "description": "The name of the knowledge base to search in."},
                            "query": {"type": "string", "description": "The search query to run against the knowledge base."},
                        },
                        "required": ["topic_name", "query"],
                    },
                },
            },
        ]

    def execute(self, tool_call: Any) -> Dict[str, Any]:
        function_name = tool_call.function.name
        arguments = json.loads(tool_call.function.arguments)
        if function_name in self.functions:
            try:
                result = self.functions[function_name](**arguments)
                return {
                    "tool_call_id": tool_call.id,
                    "role": "tool",
                    "name": function_name,
                    "content": json.dumps(result, default=str),
                }
            except Exception as e:
                return {
                    "tool_call_id": tool_call.id,
                    "role": "tool",
                    "name": function_name,
                    "content": json.dumps({"error": str(e)}),
                }
        return {
            "tool_call_id": tool_call.id,
            "role": "tool",
            "name": function_name,
            "content": json.dumps({"error": "Function not found"}),
        }

    def delegate_deep_research(self, research_instructions: str, output_schema: Dict[str, Any]) -> Dict[str, Any]:
        try:
            task = self.exa.research.create_task(
                model="exa-research-pro",
                instructions=research_instructions,
                output_schema=output_schema,
            )
            research_id = task.research_id
            result = self.exa.research.poll_until_finished(research_id)
            return {"status": "success", "research_id": research_id, "result": result.json()}
        except Exception as e:
            return {"status": "error", "message": str(e)}

    def search_and_extract(self, query: str, search_type: str, livecrawl: str, extraction_schema: Dict[str, Any]) -> Dict[str, Any]:
        try:
            results = self.exa.search_and_contents(
                query=query,
                num_results=100,
                type=search_type,
                text=True,
                livecrawl=livecrawl,
                summary={"schema": extraction_schema},
            )
            extracted_data = [json.loads(res.summary) for res in results.results if res.summary]
            return {"status": "success", "count": len(extracted_data), "data": extracted_data}
        except Exception as e:
            return {"status": "error", "message": str(e)}

    def find_similar_and_deepen(self, url: str) -> Dict[str, Any]:
        try:
            results = self.exa.find_similar_and_contents(url=url, num_results=100, text=True)
            return {
                "status": "success",
                "count": len(results.results),
                "data": [{"url": res.url, "title": res.title, "text_preview": res.text[:500]} for res in results.results],
            }
        except Exception as e:
            return {"status": "error", "message": str(e)}

    def get_full_content_and_subpages(self, url: str, subpage_limit: int) -> Dict[str, Any]:
        try:
            results = self.exa.get_contents(ids=[url], subpages=subpage_limit, text=True)
            return {
                "status": "success",
                "count": len(results.results),
                "data": [{"url": res.url, "title": res.title, "content_length": len(res.text)} for res in results.results],
            }
        except Exception as e:
            return {"status": "error", "message": str(e)}

    def add_sources_to_knowledge_base(self, topic_name: str, urls: List[str]) -> Dict[str, Any]:
        try:
            webset_id = self._get_or_create_webset(topic_name)
            # The Exa documentation implies 'search' is the agent that adds items.
            # We'll use a query designed to 'find' and thus add these specific URLs.
            query = f"Find and catalog these specific URLs: {', '.join(urls)}"
            search_task = self.exa.websets.search(webset_id=webset_id, query=query, type="company") # Type is placeholder as API requires it

            # Since the API doesn't directly confirm additions, we assume success if no error.
            items = self.exa.websets.list_items(webset_id=webset_id)
            return {"status": "success", "webset_id": webset_id, "total_items": len(items.items)}
        except Exception as e:
            return {"status": "error", "message": str(e)}

    def query_internal_knowledge_base(self, topic_name: str, query: str) -> Dict[str, Any]:
        try:
            webset_id = self._get_or_create_webset(topic_name)
            items = self.exa.websets.list_items(webset_id=webset_id, query=query, limit=100)
            return {
                "status": "success",
                "webset_id": webset_id,
                "count": len(items.items),
                "results": [{"id": item.id, "url": item.url} for item in items.items],
            }
        except Exception as e:
            return {"status": "error", "message": str(e)}

    def _get_or_create_webset(self, topic_name: str) -> str:
        # Websets API doesn't have a list or get-by-name function, so we use a simple mapping.
        # In a real production system, this would be stored in a persistent database.
        webset_id_map = {}
        if topic_name in webset_id_map:
            return webset_id_map[topic_name]

        webset = self.exa.websets.create(name=topic_name, external_id=hashlib.sha256(topic_name.encode()).hexdigest())
        webset_id_map[topic_name] = webset.id
        return webset.id

class StrategicResearchAgent:
    def __init__(self):
        Environment().load_variables()
        self.exa = Exa(api_key=os.getenv("EXA_API_KEY"))
        self.cerebras = Cerebras(api_key=os.getenv("CEREBRAS_API_KEY"))
        self.tool_executor = ToolExecutor(self.exa)
        self.thinking_model = "qwen-3-235b-a22b-thinking-2507"
        self.fast_model = "gpt-oss-120b"
        self.max_turns = 15

    def _generate_initial_schema(self, query: str) -> Dict[str, Any]:
        prompt = f"""Based on the user's query, generate a detailed JSON schema for the final research report. This schema will be used by the Exa Research API.

User Query: "{query}"

Create a JSON schema that covers all key aspects of the query. Include nested objects and arrays where appropriate. For example, for "AI in healthcare," you might include sections for 'applications', 'companies', 'ethical_concerns', and 'future_trends'. Ensure the schema is comprehensive and well-structured.

Return only the JSON schema object."""

        try:
            response = self.cerebras.chat.completions.create(
                model=self.fast_model,
                messages=[{"role": "user", "content": prompt}],
                max_tokens=8192,
                temperature=0.4,
                response_format={"type": "json_object"},
            )
            return json.loads(response.choices[0].message.content)
        except Exception:
            return {
                "$schema": "",
                "title": "General Research Report",
                "type": "object",
                "properties": {
                    "summary": {"type": "string"},
                    "key_findings": {"type": "array", "items": {"type": "string"}},
                    "sources": {"type": "array", "items": {"type": "object", "properties": {"url": {"type": "string"}, "title": {"type": "string"}}}},
                },
            }

    def run_mission(self, query: str) -> Dict[str, Any]:
        start_time = time.time()
        mission_id = hashlib.sha256(f"{query}{start_time}".encode()).hexdigest()

        system_prompt = """You are a world-class autonomous research agent. Your goal is to conduct comprehensive research based on the user's query. You have a suite of powerful tools from the Exa API at your disposal.

Your process should be strategic and iterative:
1.  **Analyze & Plan:** Understand the query. For broad topics, delegate to the `delegate_deep_research` tool first. For more specific queries, plan a sequence of `search_and_extract`, `find_similar_and_deepen`, and other tools.
2.  **Execute:** Call the most appropriate tool for the current step of your plan.
3.  **Synthesize & Reason:** Analyze the results from the tool. Update your understanding and internal state.
4.  **Decide Next Step:** Based on the new information, decide what to do next. Should you deepen the research on a specific point? Broaden the search? Or have you gathered enough information to conclude?
5.  **Build Knowledge:** As you find high-quality sources, add them to a long-term knowledge base (`add_sources_to_knowledge_base`) and query it when relevant (`query_internal_knowledge_base`).
6.  **Conclude:** When you have a comprehensive answer, synthesize all your findings into a final, detailed report for the user. Do not simply list the tool outputs. Explain your process, the insights you gained at each step, and present a final, coherent answer. Stop by responding with your final report without any further tool calls."""

        messages = [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": f"Please begin your research mission on the following topic: '{query}'"},
        ]

        tools = self.tool_executor.get_tool_definitions()

        for turn in range(self.max_turns):
            response = self.cerebras.chat.completions.create(
                model=self.thinking_model,
                messages=messages,
                tools=tools,
                max_tokens=32768,
                temperature=0.7
            )
            response_message = response.choices[0].message

            if not response_message.tool_calls:
                # Agent has finished and is providing the final report
                return {
                    "mission_id": mission_id,
                    "status": "completed",
                    "query": query,
                    "final_report": response_message.content,
                    "turn_count": turn + 1,
                    "duration_seconds": time.time() - start_time,
                    "history": messages,
                }

            messages.append(response_message.model_dump())

            for tool_call in response_message.tool_calls:
                tool_result = self.tool_executor.execute(tool_call)
                messages.append(tool_result)

        return {
            "mission_id": mission_id,
            "status": "failed_max_turns_exceeded",
            "query": query,
            "final_report": "The agent could not complete the research within the maximum number of turns.",
            "duration_seconds": time.time() - start_time,
            "history": messages,
        }

    def run_delegated_mission(self, query: str) -> Dict[str, Any]:
        start_time = time.time()
        mission_id = hashlib.sha256(f"{query}{start_time}".encode()).hexdigest()

        self.cerebras.chat.completions.create

        output_schema = self._generate_initial_schema(query)

        instructions = f"""Conduct a comprehensive, deep research investigation into the following topic: '{query}'. 
        Your goal is to produce a structured, high-quality report that covers all facets of this topic.
        Be thorough, cite sources, and ensure the information is accurate and up-to-date."""

        research_result = self.tool_executor.delegate_deep_research(
            research_instructions=instructions,
            output_schema=output_schema
        )

        if research_result.get("status") == "success":
            synthesis_prompt = f"""An automated research agent has produced the following structured JSON data based on the query: '{query}'.

Research Data:
{json.dumps(research_result.get('result', {}), indent=2)}

Your task is to synthesize this structured data into a final, comprehensive, and well-written report for the end-user. The report should be 20-30 pages long, detailed, and professional. Transform the raw JSON into a narrative, explaining the findings, drawing connections, and providing a holistic overview.

Structure your report with the following sections:
1.  **Executive Summary:** A high-level overview of the key findings.
2.  **Detailed Analysis:** A deep dive into each section of the provided data.
3.  **Insights and Implications:** What the findings mean, potential impacts, and trends.
4.  **Conclusion:** A summary of the research and final thoughts.
5.  **Sources:** A list of the sources cited in the research data.

Produce a complete and polished final report."""

            final_report_response = self.cerebras.chat.completions.create(
                model=self.thinking_model,
                messages=[{"role": "user", "content": synthesis_prompt}],
                max_tokens=32768,
                temperature=0.6,
            )

            return {
                "mission_id": mission_id,
                "status": "completed",
                "mode": "delegated",
                "query": query,
                "final_report": final_report_response.choices[0].message.content,
                "raw_research_data": research_result.get('result', {}),
                "duration_seconds": time.time() - start_time,
            }
        else:
            return {
                "mission_id": mission_id,
                "status": "failed_delegation",
                "mode": "delegated",
                "query": query,
                "error": research_result.get("message", "Unknown error during delegated research."),
                "duration_seconds": time.time() - start_time,
            }


