@app.route('/api/research', methods=['POST'])
def start_research():
    data = request.json
    query = data.get('query')
    mode = data.get('mode', 'iterative') # 'iterative' or 'delegated'

    if not query:
        return jsonify({"error": "Query is required"}), 400

    def run_task():
        if mode == 'delegated':
            result = agent.run_delegated_mission(query)
        else:
            result = agent.run_mission(query)

        # In a real app, you would store this result persistently
        print(f"Mission {result.get('mission_id')} completed. Status: {result.get('status')}")

    thread = Thread(target=run_task)
    thread.daemon = True
    thread.start()

    return jsonify({"message": "Research mission initiated. The result will be processed in the background."}), 202

@app.route('/api/research/stream', methods=['POST'])
def stream_research():
    data = request.json
    query = data.get('query')

    if not query:
        return jsonify({"error": "Query is required"}), 400

    def generate_stream():
        system_prompt = """You are a world-class autonomous research agent. Your goal is to conduct comprehensive research based on the user's query. You have a suite of powerful tools from the Exa API at your disposal. As you work, you must 'think out loud', explaining your reasoning, the tools you are choosing, and what you learn from the results at each step. This stream of consciousness is your primary output."""

        messages = [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": f"Please begin your research mission on the following topic, thinking out loud as you go: '{query}'"},
        ]
        tools = agent.tool_executor.get_tool_definitions()

        yield f"data: {json.dumps({'type': 'start', 'message': 'Agent is initializing...'})}\n\n"

        for turn in range(agent.max_turns):
            response = agent.cerebras.chat.completions.create(
                model=agent.thinking_model,
                messages=messages,
                tools=tools,
                max_tokens=32768,
                temperature=0.7,
                stream=True
            )

            collected_chunks = []
            tool_calls = []

            yield f"data: {json.dumps({'type': 'thought_start', 'turn': turn + 1})}\n\n"
            for chunk in response:
                if chunk.choices and chunk.choices[0].delta.content:
                    content = chunk.choices[0].delta.content
                    yield f"data: {json.dumps({'type': 'thought_chunk', 'content': content})}\n\n"
                    collected_chunks.append(content)
                if chunk.choices and chunk.choices[0].delta.tool_calls:
                    tool_calls.extend(chunk.choices[0].delta.tool_calls)

            yield f"data: {json.dumps({'type': 'thought_end'})}\n\n"

            full_response_content = "".join(collected_chunks)

            # Reconstruct tool calls
            if tool_calls:
                final_tool_calls = []
                for tc in tool_calls:
                    if tc.index is not None and tc.index >= len(final_tool_calls):
                        final_tool_calls.append({"id": tc.id, "type": "function", "function": {"name": "", "arguments": ""}})
                    if tc.function:
                        if tc.function.name:
                            final_tool_calls[tc.index]['function']['name'] += tc.function.name
                        if tc.function.arguments:
                            final_tool_calls[tc.index]['function']['arguments'] += tc.function.arguments

                response_message = {"role": "assistant", "content": full_response_content, "tool_calls": final_tool_calls}
                messages.append(response_message)

                for i, tool_call_data in enumerate(final_tool_calls):
                    tool_call = type('ToolCall', (object,), {'id': tool_call_data['id'], 'function': type('Function', (object,), tool_call_data['function'])})

                    yield f"data: {json.dumps({'type': 'tool_start', 'name': tool_call.function.name, 'arguments': tool_call.function.arguments})}\n\n"
                    tool_result = agent.tool_executor.execute(tool_call)
                    yield f"data: {json.dumps({'type': 'tool_end', 'result': tool_result})}\n\n"
                    messages.append(tool_result)

            else:
                yield f"data: {json.dumps({'type': 'final_report', 'content': full_response_content})}\n\n"
                yield f"data: {json.dumps({'type': 'end'})}\n\n"
                return

        yield f"data: {json.dumps({'type': 'error', 'message': 'Max turns exceeded.'})}\n\n"
        yield f"data: {json.dumps({'type': 'end'})}\n\n"

    return Response(stream_with_context(generate_stream()), mimetype='text/event-stream')


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, threaded=True)
