class ExaResearchTaskManager:
    def __init__(self, exa_client: Exa):
        self.exa = exa_client

    def create_research_task(self, instructions: str, output_schema: Dict, use_pro: bool = True) -> str:
        model = "exa-research-pro" if use_pro else "exa-research"

        try:
            task = self.exa.research.create_task(
                model=model,
                instructions=instructions,
                output_schema=output_schema
            )

            return task
        except Exception as e:
            return f"error:{str(e)}"

    def poll_research_task(self, research_id: str) -> Dict:
        try:
            result = self.exa.research.poll_until_finished(research_id)
            return {"success": True, "result": result}
        except Exception as e:
            return {"success": False, "error": str(e)}

    def get_task_status(self, research_id: str) -> Dict:
        try:
            result = self.exa.research.get_task(research_id)
            return {"success": True, "status": result}
        except Exception as e:
            return {"success": False, "error": str(e)}

class WebsetManager:
    def __init__(self, exa_client: Exa):
        self.exa = exa_client
        self.websets = {}

    def create_webset(self, name: str, external_id: str) -> Dict:
        try:
            webset = self.exa.websets.create(name=name, external_id=external_id)
            self.websets[external_id] = webset.id
            return {"success": True, "webset_id": webset.id}
        except Exception as e:
            return {"success": False, "error": str(e)}

    def add_to_webset(self, webset_id: str, query: str, search_type: str = "company") -> Dict:
        try:
            search = self.exa.websets.search(
                webset_id=webset_id,
                query=query,
                type=search_type
            )
            return {"success": True, "search_id": search}
        except Exception as e:
            return {"success": False, "error": str(e)}

    def list_webset_items(self, webset_id: str) -> Dict:
        try:
            items = self.exa.websets.list_items(webset_id=webset_id)
            return {"success": True, "items": items}
        except Exception as e:
            return {"success": False, "error": str(e)}

class UpstashRedisClient:
    def __init__(self, url: str, token: str):
        self.url = url.rstrip('/')
        self.token = token
        self.headers = {"Authorization": f"Bearer {token}"}

    def setex(self, key: str, seconds: int, value: str):
        try:
            response = requests.post(
                f"{self.url}/setex/{key}/{seconds}",
                headers=self.headers,
                data=value
            )
            return response.json()
        except:
            return None

    def get(self, key: str):
        try:
            response = requests.get(
                f"{self.url}/get/{key}",
                headers=self.headers
            )
            result = response.json().get("result")
            if result:
                return result.encode() if isinstance(result, str) else result
            return None
        except:
            return None

    def publish(self, channel: str, message: str):
        try:
            response = requests.post(
                f"{self.url}/publish/{channel}",
                headers=self.headers,
                data=message
            )
            return response.json()
        except:
            return None

    def pubsub(self):
        return UpstashPubSub(self.url, self.token)

class UpstashPubSub:
    def __init__(self, url: str, token: str):
        self.url = url
        self.token = token
        self.subscribed_channels = []

    def subscribe(self, channel: str):
        self.subscribed_channels.append(channel)

    def listen(self):
        for i in range(600):
            yield {"type": "message", "data": json.dumps({"status": "listening"})}
            time.sleep(1)

class CerebrasToolAgent:
    def __init__(self, cerebras_client: Cerebras, exa_orchestrator: ExaToolOrchestrator):
        self.cerebras = cerebras_client
        self.exa_tools = exa_orchestrator
        self.conversation_history = []

    def execute_multi_turn_research(self, initial_query: str, max_turns: int = 15) -> Dict:
        messages = [
            {
                "role": "system",
                "content": "You are an expert research agent with access to Exa search tools. Your goal is to conduct thorough, multi-step research by strategically using the available tools. Think carefully about what information you need and which tool to use at each step. When you have gathered sufficient information, provide a comprehensive synthesis."
            },
            {
                "role": "user",
                "content": f"Research this query comprehensively: {initial_query}\n\nUse the available tools strategically to gather information from multiple angles. After sufficient research, provide a detailed synthesis."
            }
        ]

        tools_used = []
        gathered_data = []

        for turn in range(max_turns):
            try:
                response = self.cerebras.chat.completions.create(
                    model="qwen-3-235b-a22b-thinking-2507",
                    messages=messages,
                    tools=self.exa_tools.tool_registry,
                    max_tokens=32768,
                    temperature=0.7
                )

                assistant_message = response.choices[0].message

                if not assistant_message.tool_calls:
                    final_synthesis = assistant_message.content
                    return {
                        "success": True,
                        "synthesis": final_synthesis,
                        "tools_used": tools_used,
                        "gathered_data": gathered_data,
                        "turns": turn + 1
                    }

                messages.append(assistant_message.model_dump())

                for tool_call in assistant_message.tool_calls:
                    function_name = tool_call.function.name
                    function_args = json.loads(tool_call.function.arguments)

                    tools_used.append({
                        "turn": turn + 1,
                        "tool": function_name,
                        "arguments": function_args
                    })

                    tool_result = self.exa_tools.execute_tool(function_name, function_args)

                    if tool_result.get("success"):
                        gathered_data.extend(tool_result.get("results", []))

                    messages.append({
                        "role": "tool",
                        "tool_call_id": tool_call.id,
                        "content": json.dumps(tool_result)
                    })

            except Exception as e:
                return {
                    "success": False,
                    "error": str(e),
                    "tools_used": tools_used,
                    "gathered_data": gathered_data,
                    "turns": turn + 1
                }

        return {
            "success": True,
            "synthesis": "Research reached maximum turns without final synthesis",
            "tools_used": tools_used,
            "gathered_data": gathered_data,
            "turns": max_turns
        }

