        self.redis_dragonfly_2 = redis.from_url("rediss://default:ddakvoa79hk3@0hxia2s5w.dragonflydb.cloud:6385")
        self.redis_dragonfly_3 = redis.from_url("rediss://default:4s6z877px3x1@zy0n0f6e8.dragonflydb.cloud:6385")

        self.exa_orchestrator = ExaToolOrchestrator(self.exa)
        self.research_manager = ExaResearchTaskManager(self.exa)
        self.webset_manager = WebsetManager(self.exa)
        self.cerebras_agent = CerebrasToolAgent(self.cerebras, self.exa_orchestrator)

        self.state_lock = Lock()
        self.research_state = {
            "session_id": None,
            "query": "",
            "status": "idle",
            "progress": 0,
            "current_action": "",
            "current_phase": "",
            "thought_stream": [],
            "sources": [],
            "research_tasks": [],
            "tool_calls": [],
            "websets_created": [],
            "structured_data": [],
            "start_time": None
        }

    def generate_session_id(self, query: str) -> str:
        timestamp = str(time.time())
        return hashlib.sha256(f"{query}{timestamp}".encode()).hexdigest()[:16]

    def update_state(self, **kwargs):
        with self.state_lock:
            for key, value in kwargs.items():
                self.research_state[key] = value
            self._persist_state()
            self._broadcast_state()

    def add_thought(self, thought: str, thought_type: str = "observation"):
        with self.state_lock:
            self.research_state["thought_stream"].append({
                "timestamp": time.time(),
                "type": thought_type,
                "content": thought
            })
            self._broadcast_state()

    def _persist_state(self):
        session_id = self.research_state.get("session_id")
        if session_id:
            state_json = json.dumps(self.research_state, default=str)

            self.redis_upstash.setex(f"session:{session_id}", 7200, state_json)

            for redis_client in [self.redis_dragonfly_1, self.redis_dragonfly_2, self.redis_dragonfly_3]:
                try:
                    redis_client.setex(f"session:{session_id}", 7200, state_json)
                except:
                    pass

    def _broadcast_state(self):
        session_id = self.research_state.get("session_id")
        if session_id:
            try:
                self.redis_upstash.publish(f"research_updates:{session_id}", json.dumps(self.research_state, default=str))
            except:
                pass

    def get_state(self, session_id: str) -> Dict:
        state = self.redis_upstash.get(f"session:{session_id}")
        if state:
            return json.loads(state.decode() if isinstance(state, bytes) else state)

        for redis_client in [self.redis_dragonfly_1, self.redis_dragonfly_2, self.redis_dragonfly_3]:
            try:
                state = redis_client.get(f"session:{session_id}")
                if state:
                    return json.loads(state)
            except:
                continue
        return {}

    def create_dynamic_output_schema(self, query: str) -> Dict:
        self.add_thought("Generating dynamic output schema for structured research", "planning")

        schema_prompt = f"""Create a JSON schema for structured research output on this query: {query}

Design a schema with 3-7 top-level fields that capture the most important structured information for this topic. Use appropriate data types (string, number, array, object). Include enums where applicable to reduce hallucination.

Return ONLY the JSON schema in this format:
{{
    "type": "object",
    "properties": {{
        "field_name": {{"type": "string", "description": "..."}},
        ...
    }},
    "required": ["field1", "field2"]
}}"""

        try:
            response = self.cerebras.chat.completions.create(
                model="gpt-oss-120b",
                messages=[{"role": "user", "content": schema_prompt}],
                max_tokens=4096,
                temperature=0.6
            )

            schema = json.loads(response.choices[0].message.content)
            self.add_thought(f"Schema created with {len(schema.get('properties', {}))} fields", "planning")
            return schema

        except Exception as e:
            self.add_thought(f"Schema generation failed: {str(e)}", "error")
            return {
                "type": "object",
                "properties": {
                    "summary": {"type": "string"},
                    "key_findings": {"type": "array", "items": {"type": "string"}},
                    "sources": {"type": "array", "items": {"type": "string"}}
                },
                "required": ["summary"]
            }

    def launch_exa_research_tasks(self, query: str) -> List[str]:
        self.add_thought("Launching high-level Exa Research API tasks", "action")

        task_configs = [
            {
                "instructions": f"Research this comprehensively: {query}. Focus on current state, key players, recent developments, and future outlook.",
                "pro": True
            },
            {
                "instructions": f"Find and analyze the top experts, companies, and organizations related to: {query}",
                "pro": False
            },
            {
                "instructions": f"Identify controversies, debates, challenges, and risks associated with: {query}",
                "pro": False
            }
        ]

        research_ids = []

        for config in task_configs:
            schema = self.create_dynamic_output_schema(f"{query} - {config['instructions'][:50]}")

            research_id = self.research_manager.create_research_task(
                instructions=config["instructions"],
                output_schema=schema,
                use_pro=config["pro"]
            )

            if not research_id.startswith("error:"):
                research_ids.append(research_id)
                self.add_thought(f"Research task created: {research_id}", "action")
            else:
                self.add_thought(f"Research task failed: {research_id}", "error")

        with self.state_lock:
            self.research_state["research_tasks"] = research_ids

        return research_ids

    def create_topic_webset(self, query: str) -> str:
        self.add_thought("Creating dedicated Webset for long-term knowledge base", "action")

        external_id = f"webset_{self.research_state.get('session_id', 'unknown')}"
        result = self.webset_manager.create_webset(
            name=f"Research: {query[:100]}",
            external_id=external_id
        )

        if result.get("success"):
            webset_id = result.get("webset_id")
            self.add_thought(f"Webset created: {webset_id}", "action")

            with self.state_lock:
                self.research_state["websets_created"].append(webset_id)

            return webset_id
        else:
            self.add_thought(f"Webset creation failed: {result.get('error')}", "error")
            return None

    def populate_webset(self, webset_id: str, query: str):
        if not webset_id:
            return

        self.add_thought("Populating Webset with high-quality sources", "action")

        search_queries = [
            f"{query} key players companies",
            f"{query} research papers",
            f"{query} latest news developments",
            f"{query} expert analysis"
        ]

        for search_query in search_queries:
            self.webset_manager.add_to_webset(webset_id, search_query, "company")

    def execute_cerebras_tool_research(self, query: str) -> Dict:
        self.add_thought("Executing multi-turn tool-use research with Cerebras agent", "action")

        result = self.cerebras_agent.execute_multi_turn_research(query, max_turns=20)

        if result.get("success"):
            self.add_thought(f"Tool research completed: {len(result.get('tools_used', []))} tools used across {result.get('turns', 0)} turns", "insight")

            with self.state_lock:
                self.research_state["tool_calls"] = result.get("tools_used", [])
                self.research_state["sources"].extend(result.get("gathered_data", []))
        else:
            self.add_thought(f"Tool research error: {result.get('error')}", "error")

        return result

    def gather_structured_data(self, query: str) -> List[Dict]:
        self.add_thought("Extracting structured data with dynamic schemas", "action")

        topics = [
            f"{query} companies and organizations",
            f"{query} key statistics and metrics",
            f"{query} expert opinions and perspectives"
        ]

        structured_results = []

        for topic in topics:
            schema = self.create_dynamic_output_schema(topic)

            result = self.exa_orchestrator.execute_tool(
                "exa_structured_summary",
                {
                    "query": topic,
                    "schema": schema,
                    "num_results": 50
                }
            )

            if result.get("success"):
                structured_results.extend(result.get("results", []))
                self.add_thought(f"Structured data extracted for: {topic}", "discovery")

        with self.state_lock:
            self.research_state["structured_data"] = structured_results

        return structured_results

    def poll_research_tasks(self, research_ids: List[str]) -> List[Dict]:
        self.add_thought("Polling Exa Research tasks for completion", "action")

        results = []

        with ThreadPoolExecutor(max_workers=5) as executor:
            futures = {executor.submit(self.research_manager.poll_research_task, rid): rid for rid in research_ids}

            for future in as_completed(futures):
                rid = futures[future]
                result = future.result()

                if result.get("success"):
                    self.add_thought(f"Research task {rid} completed", "discovery")
                    results.append(result.get("result"))
                else:
                    self.add_thought(f"Research task {rid} failed: {result.get('error')}", "error")

        return results

    def synthesize_final_report(self, query: str, tool_research: Dict, exa_research_results: List[Dict], structured_data: List[Dict]) -> str:
        self.add_thought("Synthesizing comprehensive final report", "synthesis")

        tool_synthesis = tool_research.get("synthesis", "")
        tool_sources = tool_research.get("gathered_data", [])

        sources_text = "\n\n".join([
            f"[{i+1}] {s.get('title', 'Untitled')} ({s.get('url', '')})\n{s.get('text', '')[:2000]}"
            for i, s in enumerate(tool_sources[:200])
        ])

        exa_research_text = "\n\n".join([
            f"Research Task {i+1}:\n{json.dumps(result, indent=2)[:5000]}"
            for i, result in enumerate(exa_research_results)
        ])

        structured_text = "\n\n".join([
            f"Structured Data {i+1}:\n{json.dumps(item.get('structured_data', {}), indent=2)[:1000]}"
            for i, item in enumerate(structured_data[:100])
        ])

        report_prompt = f"""Generate an exceptional, comprehensive research report (25-35 pages equivalent).

Query: {query}

Multi-turn tool-based research synthesis:
{tool_synthesis[:20000]}

High-level Exa Research API results:
{exa_research_text[:30000]}

Structured data extractions:
{structured_text[:20000]}

Sources analyzed:
{sources_text[:60000]}

Create a masterful report with:

# EXECUTIVE SUMMARY (2-3 pages)
Key findings, implications, recommendations

# RESEARCH METHODOLOGY (2 pages)
- Multi-level approach (tool-based + research API)
- Structured data extraction
- Knowledge base creation
- Quality assurance

# COMPREHENSIVE FINDINGS (15-20 pages)
Organize into 6-8 thematic sections with:
- Deep analysis
- Evidence from multiple sources
- Structured data insights
- Expert perspectives
- Cross-references

# STRUCTURED DATA ANALYSIS (3-4 pages)
Insights from quantitative structured data

# STRATEGIC INSIGHTS (3-4 pages)
- Patterns identified
- Correlations discovered
- Unexpected findings
- Future implications

# RECOMMENDATIONS (3-4 pages)
- Actionable recommendations
- Strategic considerations
- Implementation roadmap

# FUTURE OUTLOOK (2-3 pages)
- Emerging trends
- Predictions
- Scenarios

# CONCLUSION (1-2 pages)
Final synthesis

# REFERENCES
Comprehensive source list

Make it authoritative, evidence-based, and exceptionally thorough."""

        try:
            body = json.dumps({
                "anthropic_version": "bedrock-2023-05-31",
                "max_tokens": 200000,
                "messages": [{"role": "user", "content": report_prompt}],
                "temperature": 0.65
            })

            response = self.bedrock.invoke_model(
                modelId="anthropic.claude-sonnet-4-5-v2:0",
                body=body
            )

            response_body = json.loads(response["body"].read())
            report = response_body["content"][0]["text"]

            enhancement_prompt = f"""Enhance this report with even greater depth and sophistication:

{report[:120000]}

Add more specific examples, deeper analysis, additional perspectives, and stronger evidence chains.

Return the enhanced final report."""

            body2 = json.dumps({
                "anthropic_version": "bedrock-2023-05-31",
                "max_tokens": 200000,
                "messages": [{"role": "user", "content": enhancement_prompt}],
                "temperature": 0.6
            })

            response2 = self.bedrock.invoke_model(
                modelId="anthropic.claude-sonnet-4-5-v2:0",
                body=body2
            )

            response_body2 = json.loads(response2["body"].read())
            final_report = response_body2["content"][0]["text"]

            return final_report

        except Exception as e:
            self.add_thought(f"Report synthesis error: {str(e)}", "error")
            return f"Error generating report: {str(e)}\n\nPartial content:\n{tool_synthesis[:10000]}"

    def autonomous_research_workflow(self, query: str) -> Dict:
        session_id = self.generate_session_id(query)
        start_time = time.time()

        with self.state_lock:
            self.research_state = {
                "session_id": session_id,
                "query": query,
                "status": "running",
                "progress": 0,
                "current_action": "Initializing advanced research system",
                "current_phase": "Initialization",
                "thought_stream": [],
                "sources": [],
                "research_tasks": [],
                "tool_calls": [],
                "websets_created": [],
                "structured_data": [],
                "start_time": start_time
            }

        self._broadcast_state()

        try:
            self.add_thought("System initialized. Beginning advanced research workflow.", "system")
            self.update_state(progress=2)

            webset_id = self.create_topic_webset(query)
            self.update_state(progress=5)

            if webset_id:
                self.populate_webset(webset_id, query)
            self.update_state(progress=8)

            research_ids = self.launch_exa_research_tasks(query)
            self.update_state(progress=15)

            self.add_thought("Launching parallel multi-turn tool research", "action")
            tool_research_result = self.execute_cerebras_tool_research(query)
            self.update_state(progress=50)

            self.add_thought("Gathering structured data with dynamic schemas", "action")
            structured_data = self.gather_structured_data(query)
            self.update_state(progress=65)

            self.add_thought("Waiting for high-level research tasks to complete", "action")
            exa_research_results = self.poll_research_tasks(research_ids)
            self.update_state(progress=80)

            self.add_thought("Synthesizing comprehensive final report", "synthesis")
            final_report = self.synthesize_final_report(
                query,
                tool_research_result,
                exa_research_results,
                structured_data
            )
            self.update_state(progress=95)

            self.add_thought("Research workflow completed successfully", "system")

            self.update_state(
                status="completed",
                progress=100,
                current_action="Research completed",
                current_phase="Completed"
            )

            result = {
                "session_id": session_id,
                "query": query,
                "report": final_report,
                "metadata": {
                    "duration_seconds": time.time() - start_time,
                    "total_sources": len(self.research_state["sources"]),
                    "tool_calls": len(self.research_state["tool_calls"]),
                    "research_tasks": len(research_ids),
                    "structured_data_items": len(structured_data),
                    "websets_created": self.research_state["websets_created"]
                },
                "thought_stream": self.research_state["thought_stream"],
                "sources": self.research_state["sources"][:200],
                "tool_calls": self.research_state["tool_calls"],
                "structured_data": structured_data[:100]
            }

            result_json = json.dumps(result, default=str)

            self.redis_upstash.setex(f"report:{session_id}", 86400, result_json)

            for redis_client in [self.redis_dragonfly_1, self.redis_dragonfly_2, self.redis_dragonfly_3]:
                try:
                    redis_client.setex(f"report:{session_id}", 86400, result_json)
                except:
                    pass

            return result

        except Exception as e:
            self.add_thought(f"Error occurred: {str(e)}", "error")

            self.update_state(
                status="error",
                current_action=f"Error: {str(e)}",
                current_phase="Error"
            )

            return {
                "session_id": session_id,
                "error": str(e),
                "partial_state": self.research_state
            }

app = Flask(__name__)
CORS(app)

system = AdvancedDeepSearchSystem()

@app.route("/api/research", methods=["POST"])
def start_research():
    data = request.json
    query = data.get("query", "")

    if not query:
        return jsonify({"error": "Query is required"}), 400

    session_id = system.generate_session_id(query)

    def research_task():
        system.autonomous_research_workflow(query)

    thread = Thread(target=research_task)
    thread.daemon = True
    thread.start()

    return jsonify({"session_id": session_id})

@app.route("/api/status/<session_id>", methods=["GET"])
def get_status(session_id):
    state = system.get_state(session_id)
    if not state:
        return jsonify({"error": "Session not found"}), 404
    return jsonify(state)

@app.route("/api/stream/<session_id>", methods=["GET"])
def stream_status(session_id):
    def generate():
        pubsub = system.redis_upstash.pubsub()
        pubsub.subscribe(f"research_updates:{session_id}")

        timeout_counter = 0
        for message in pubsub.listen():
            if message["type"] == "message":
                yield f"data: {message['data']}\n\n"

            timeout_counter += 1
            if timeout_counter > 600:
                break

    return Response(stream_with_context(generate()), mimetype="text/event-stream")

@app.route("/api/report/<session_id>", methods=["GET"])
def get_report(session_id):
    report_data = system.redis_upstash.get(f"report:{session_id}")
    if report_data:
        return jsonify(json.loads(report_data.decode() if isinstance(report_data, bytes) else report_data))

    for redis_client in [system.redis_dragonfly_1, system.redis_dragonfly_2, system.redis_dragonfly_3]:
        try:
            report_data = redis_client.get(f"report:{session_id}")
            if report_data:
                return jsonify(json.loads(report_data))
        except:
            continue

    return jsonify({"error": "Report not found"}), 404

